# frozen_string_literal: true

module Aspera
  # Test coverage with SimpleCov, enabled with env var `ENABLE_COVERAGE`.
  # Each tested process stores only its own result in `parts/<uuid>`: merging all results at each process exit is slow when there are many processes.
  # The report is generated by `report`, which merges all parts (called by the test Rake tasks).
  module Coverage
    # Development top folder, computed from this source location
    ROOT = File.dirname(File.realpath(__FILE__), 3)
    # Report folder, relative to `ROOT`
    DIR = 'tmp/coverage'
    # One sub-folder per process, each with its own `.resultset.json`
    PARTS = File.join(DIR, 'parts')
    # Results are kept for 1 day (must be longer than time to run the whole test suite, possibly in several runs)
    MERGE_TIMEOUT = 86_400
    # Lines with those words are ignored from coverage (assertions usually do not trigger)
    NO_COV_FUNCTIONS = %w[error_unreachable_line error_unexpected_value Log.log.trace].freeze
    # No coverage in these files or folders
    NO_COV_PATHS = %w[
      build/
      tmp/
      lib/transferd_pb.rb
      lib/transferd_services_pb.rb
      lib/aspera/secret/store/macos_security.rb
      lib/aspera/assert.rb
    ].freeze
    private_constant :MERGE_TIMEOUT, :NO_COV_FUNCTIONS, :NO_COV_PATHS

    class << self
      # Start coverage of current process.
      # Must be called before any library is loaded.
      def start
        require 'simplecov'
        require 'securerandom'
        name = SecureRandom.uuid
        SimpleCov.root(ROOT)
        SimpleCov.coverage_dir(File.join(PARTS, name))
        SimpleCov.command_name(name)
        SimpleCov.merge_subprocesses(true)
        SimpleCov.merge_timeout(MERGE_TIMEOUT)
        # The trend of a single process is meaningless
        SimpleCov.history_limit(0)
        # Only store this process result (in its own folder): no report
        SimpleCov.at_exit { SimpleCov.result }
        SimpleCov.start { Aspera::Coverage.filters(self) }
      end

      # Merge the results of all processes and generate the report in `DIR`.
      # Results older than `MERGE_TIMEOUT` are deleted.
      # @return [Boolean] `false` if there is no result
      def report
        require 'simplecov'
        require 'fileutils'
        require 'etc'
        parts = Dir.glob(File.join(ROOT, PARTS, '*'))
        old, parts = parts.partition { |dir| Time.now - File.mtime(dir) > MERGE_TIMEOUT }
        FileUtils.rm_rf(old)
        results = parts.map { |dir| File.join(dir, '.resultset.json') }.select { |file| File.exist?(file) }
        return false if results.empty?
        # Else the merged result would be added to the previous one
        FileUtils.rm_f(File.join(ROOT, DIR, '.resultset.json'))
        SimpleCov.root(ROOT)
        SimpleCov.coverage_dir(DIR)
        # The merged command name lists all process UUIDs: show their number instead
        SimpleCov.at_exit do
          result = SimpleCov.result
          result.command_name = "#{result.command_names.size} processes"
          result.format!
        end
        SimpleCov.collate(results, processes: Etc.nprocessors) { Aspera::Coverage.filters(self) }
        true
      end

      # Configure filters (in `SimpleCov.start` or `SimpleCov.collate` block)
      # @param config [SimpleCov] Receiver of the configuration block
      def filters(config)
        config.skip do |source_file|
          source_file.lines.each do |line|
            line.skipped! if NO_COV_FUNCTIONS.any? { |i| line.src.include?(i) }
          end
          false
        end
        NO_COV_PATHS.each { |path| config.skip(path) }
      end
    end
  end
end

# Start coverage when this file is loaded, if enabled: must be required before any other library
Aspera::Coverage.start if ENV.key?('ENABLE_COVERAGE')
